def expand_template(template: str, values: dict[str, str]) -> str:
    out = []
    i = 0
    n = len(template)
    while i < n:
        if template.startswith('{{', i):
            out.append('{')
            i += 2
        elif template.startswith('}}', i):
            out.append('}')
            i += 2
        elif template[i] == '{':
            j = template.find('}', i + 1)
            if j == -1:
                out.append('{')
                i += 1
            else:
                key = template[i + 1:j]
                if key in values:
                    out.append(values[key])
                else:
                    out.append(template[i:j + 1])
                i = j + 1
        else:
            out.append(template[i])
            i += 1
    return ''.join(out)

def decode_runs(encoded: str) -> str:
    out = []
    i = 0
    n = len(encoded)
    while i < n:
        if encoded[i] == '\\':
            ch = encoded[i + 1]
            i += 2
        else:
            ch = encoded[i]
            i += 1
        if i < n and encoded[i] == '~':
            i += 1
            j = i
            while j < n and encoded[j] in '0123456789':
                j += 1
            out.append(ch * int(encoded[i:j]))
            i = j
        else:
            out.append(ch)
    return ''.join(out)

import re


def tidy_punctuation(text: str) -> str:
    s = ' '.join(text.split())
    s = re.sub(r' (?=[,.;:!?])', '', s)
    s = re.sub(r'([,.;:!?])(?=[A-Za-z])', r'\1 ', s)
    chars = list(s)
    if chars:
        chars[0] = chars[0].upper()
    for i in range(2, len(chars)):
        if chars[i - 1] == ' ' and chars[i - 2] in '.!?':
            chars[i] = chars[i].upper()
    return ''.join(chars)

def identifier_to_snake(name: str) -> str:
    words = []
    for piece in name.replace('-', '_').split('_'):
        if not piece:
            continue
        cur = piece[0]
        for i in range(1, len(piece)):
            p, c = piece[i - 1], piece[i]
            nxt = piece[i + 1] if i + 1 < len(piece) else ''
            if p.islower() and c.isupper():
                split = True
            elif p.isalpha() != c.isalpha():
                split = True
            elif p.isupper() and c.isupper() and nxt.islower():
                split = True
            else:
                split = False
            if split:
                words.append(cur)
                cur = c
            else:
                cur += c
        words.append(cur)
    return '_'.join(w.lower() for w in words)

def free_slots(busy: list[tuple[int, int]], day_start: int, day_end: int, min_len: int) -> list[tuple[int, int]]:
    if day_start >= day_end:
        return []
    clipped = []
    for s, e in busy:
        if s < e:
            s2, e2 = max(s, day_start), min(e, day_end)
            if s2 < e2:
                clipped.append((s2, e2))
    clipped.sort()
    result = []
    cur = day_start
    for s, e in clipped:
        if s > cur and s - cur >= min_len:
            result.append((cur, s))
        cur = max(cur, e)
    if day_end > cur and day_end - cur >= min_len:
        result.append((cur, day_end))
    return result

def schedule_jobs(jobs: list[tuple[str, int, int]]) -> list[str]:
    order = sorted(range(len(jobs)), key=lambda i: (-jobs[i][2], i))
    slots = {}
    for i in order:
        name, deadline, profit = jobs[i]
        t = deadline
        while t >= 1 and t in slots:
            t -= 1
        if t >= 1:
            slots[t] = name
    return [slots[t] for t in sorted(slots)]

